		return Freshness{Kind: "fresh", AsOf: &nowStr}
	}
	bucket := (age.Milliseconds() / ageBucketMsGranularity) * ageBucketMsGranularity
	return Freshness{Kind: "stale", AsOf: &nowStr, AgeBucketMs: &bucket}
