    console.log(JSON.stringify(afterReload, null, 2));
    await page.screenshot({ path: join(outDir, 'survives-page-reload.png'), fullPage: false });

    console.log(`\nScreenshots + computed-style evidence written to ${outDir}`);
  } finally {
    await server.stop();
  }
} finally {
  await browser.close();
  cleanup();
}

